**Approach**

A heap is a complete binary tree where every parent compares favourably to its children. A priority queue is the abstract operation — "give me the most important item" — and a heap is the usual implementation.

**Logic**

The heap property is *local*: each parent beats its children. It says nothing about siblings, which is why a heap is not sorted and why in-order traversal of it is meaningless.

Completeness is what allows the array layout with children at 2i+1 and 2i+2 and no pointers at all — that contiguity is why heaps have such good cache behaviour.

Insert and extract are O(log n) by sifting along one root-to-leaf path. Building from an existing array is O(n), not O(n log n), which is a genuinely surprising result.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    private class MinHeap
    {
        private readonly List<int> _items = new();
        public int Count => _items.Count;

        public void Push(int value)
        {
            _items.Add(value);
            int i = _items.Count - 1;

            // Sift up along ONE path: O(log n).
            while (i > 0)
            {
                int parent = (i - 1) / 2;
                if (_items[parent] <= _items[i]) break;
                (_items[parent], _items[i]) = (_items[i], _items[parent]);
                i = parent;
            }
        }

        public int Pop()
        {
            int top = _items[0];
            _items[0] = _items[^1];
            _items.RemoveAt(_items.Count - 1);

            int i = 0;
            while (true)
            {
                int left = 2 * i + 1, right = 2 * i + 2, smallest = i;

                if (left < _items.Count && _items[left] < _items[smallest]) smallest = left;
                if (right < _items.Count && _items[right] < _items[smallest]) smallest = right;
                if (smallest == i) break;

                (_items[i], _items[smallest]) = (_items[smallest], _items[i]);
                i = smallest;
            }

            return top;
        }

        public string Layout => string.Join(",", _items);
    }

    public static void Main()
    {
        var heap = new MinHeap();
        foreach (int v in new[] { 5, 3, 8, 1, 9, 2 }) heap.Push(v);

        // The array is NOT sorted - only the parent-child rule holds.
        Console.WriteLine($"internal array: {heap.Layout}");

        var drained = new List<int>();
        while (heap.Count > 0) drained.Add(heap.Pop());
        Console.WriteLine($"popped in order: {string.Join(",", drained)}");

        // .NET's PriorityQueue: the priority is separate from the item.
        var queue = new PriorityQueue<string, int>();
        queue.Enqueue("write tests", 2);
        queue.Enqueue("fix outage", 1);
        queue.Enqueue("refactor", 3);

        var order = new List<string>();
        while (queue.Count > 0) order.Add(queue.Dequeue());
        Console.WriteLine($"by priority: {string.Join(" -> ", order)}");

        // A max-heap is a min-heap with the priority negated.
        var max = new PriorityQueue<int, int>();
        foreach (int v in new[] { 5, 3, 8 }) max.Enqueue(v, -v);
        Console.WriteLine($"largest first: {max.Dequeue()}");
    }
}
```

