**Approach**

Two indices moving over a sequence under a rule that lets each advance monotonically, so the whole scan is linear rather than quadratic.

**Logic**

They are the same idea with different rules. Opposing pointers move toward each other, driven by a comparison — valid when the data is sorted, because that is what makes discarding one side provably safe. A sliding window has both pointers moving forward, one expanding and one contracting under a validity condition.

The requirement in both cases is monotonicity: advancing a pointer must never need to be undone. That is why the window works for all-positive sums and breaks the moment negatives appear.

O(n), because each pointer traverses the sequence once.

**Program**

```csharp
using System;

public class Solution
{
    // Opposing pointers: valid because the array is SORTED.
    private static (int, int) TwoSumSorted(int[] sorted, int target)
    {
        int lo = 0, hi = sorted.Length - 1;

        while (lo < hi)
        {
            int sum = sorted[lo] + sorted[hi];

            if (sum == target) return (lo, hi);
            if (sum < target) lo++; else hi--;   // discard the side that cannot help
        }

        return (-1, -1);
    }

    // Sliding window: valid because all values are POSITIVE.
    private static int ShortestSubarrayAtLeast(int[] positives, int target)
    {
        int left = 0, best = int.MaxValue;
        long sum = 0;

        for (int right = 0; right < positives.Length; right++)
        {
            sum += positives[right];

            while (sum >= target)
            {
                best = Math.Min(best, right - left + 1);
                sum -= positives[left++];
            }
        }

        return best == int.MaxValue ? 0 : best;
    }

    private static long CountSteps(int[] nums, int target)
    {
        long steps = 0;
        int left = 0;
        long sum = 0;

        for (int right = 0; right < nums.Length; right++)
        {
            sum += nums[right]; steps++;
            while (sum >= target) { sum -= nums[left++]; steps++; }
        }

        return steps;
    }

    public static void Main()
    {
        var sorted = new[] { 1, 3, 4, 6, 8, 11 };
        Console.WriteLine($"two sum to 10: indices {TwoSumSorted(sorted, 10)}");
        Console.WriteLine($"two sum to 100: indices {TwoSumSorted(sorted, 100)}");

        Console.WriteLine($"shortest subarray >= 7: {ShortestSubarrayAtLeast(new[] { 2, 3, 1, 2, 4, 3 }, 7)}");
        Console.WriteLine($"target unreachable: {ShortestSubarrayAtLeast(new[] { 1, 1 }, 7)}");

        // Linear, not quadratic: each pointer crosses the array once.
        Console.WriteLine();
        Console.WriteLine($"{"n",8}{"window steps",16}{"n^2",14}");

        foreach (int n in new[] { 100, 1000, 10000 })
        {
            var values = new int[n];
            Array.Fill(values, 1);
            Console.WriteLine($"{n,8}{CountSteps(values, 5),16}{(long)n * n,14}");
        }
    }
}
```

