**Approach**

A trie stores strings by their characters along tree paths, so a shared prefix is stored once. Lookup is O(length) and independent of how many words the structure holds.

**Logic**

The defining property is that the key is the *path*, not a value in a node. That is what makes prefix queries natural — finding all words starting with a prefix means walking to one node and collecting the subtree, which no hash table can do.

The cost is memory: a node per distinct prefix position, each with child slots. A dense array of 26 is fast but wasteful on sparse data; a map per node trades speed for space.

The program counts nodes against total characters to show the prefix sharing concretely.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    private class Node
    {
        public readonly Dictionary<char, Node> Children = new();
        public bool IsWord;
    }

    private class Trie
    {
        private readonly Node _root = new();
        public int NodeCount { get; private set; } = 1;

        public void Insert(string word)
        {
            var node = _root;

            foreach (char c in word)
            {
                if (!node.Children.TryGetValue(c, out var next))
                {
                    node.Children[c] = next = new Node();
                    NodeCount++;                      // a new node only for an UNSHARED prefix
                }
                node = next;
            }

            node.IsWord = true;
        }

        public bool Contains(string word)
        {
            var node = Walk(word);
            return node != null && node.IsWord;
        }

        public IList<string> WithPrefix(string prefix)
        {
            var found = new List<string>();
            var start = Walk(prefix);
            if (start != null) Collect(start, prefix, found);
            return found;
        }

        private Node Walk(string text)
        {
            var node = _root;

            foreach (char c in text)
                if (!node.Children.TryGetValue(c, out node)) return null;

            return node;
        }

        private static void Collect(Node node, string soFar, IList<string> into)
        {
            if (node.IsWord) into.Add(soFar);

            foreach (var pair in node.Children.OrderBy(p => p.Key))
                Collect(pair.Value, soFar + pair.Key, into);
        }
    }

    public static void Main()
    {
        var words = new[] { "car", "card", "care", "careful", "cat", "dog", "do" };
        var trie = new Trie();
        foreach (string w in words) trie.Insert(w);

        Console.WriteLine($"words: {words.Length}, total characters: {words.Sum(w => w.Length)}, " +
                          $"trie nodes: {trie.NodeCount}");

        Console.WriteLine($"contains \"care\": {trie.Contains("care")}");
        Console.WriteLine($"contains \"car\": {trie.Contains("car")}");
        Console.WriteLine($"contains \"ca\": {trie.Contains("ca")}   (a prefix is not a word)");

        Console.WriteLine($"prefix \"car\": {string.Join(",", trie.WithPrefix("car"))}");
        Console.WriteLine($"prefix \"do\":  {string.Join(",", trie.WithPrefix("do"))}");
        Console.WriteLine($"prefix \"z\":   [{string.Join(",", trie.WithPrefix("z"))}]");

        Console.WriteLine();
        Console.WriteLine("lookup O(length), independent of how many words are stored");
        Console.WriteLine("prefix queries are the point - a hash table cannot do them");
        Console.WriteLine("used for autocomplete, spell check, IP routing tables, word games");
    }
}
```

