**Approach**

BFS finds the path with the fewest edges; Dijkstra finds the path with the lowest total weight. On an unweighted graph they agree, and BFS is faster. The program builds a graph where they disagree.

**Logic**

BFS uses a queue, so nodes are settled in order of edge count. That is only the shortest path when every edge costs the same — the queue has no way to express that a two-edge route might be more expensive than a five-edge one.

Dijkstra replaces the queue with a priority queue ordered by accumulated cost, so nodes are settled in cost order instead. BFS is Dijkstra with all weights equal to one.

Dijkstra requires non-negative weights; a negative edge breaks the settle-once rule and needs Bellman-Ford.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    private static readonly (int To, int Weight)[][] Graph =
    {
        /* 0 */ new[] { (1, 10), (2, 1) },
        /* 1 */ new[] { (4, 10) },
        /* 2 */ new[] { (3, 1) },
        /* 3 */ new[] { (4, 1) },
        /* 4 */ Array.Empty<(int, int)>()
    };

    private static (int Edges, int Cost) Bfs(int start, int target)
    {
        var edges = new Dictionary<int, int> { [start] = 0 };
        var cost = new Dictionary<int, int> { [start] = 0 };
        var queue = new Queue<int>();
        queue.Enqueue(start);

        while (queue.Count > 0)
        {
            int node = queue.Dequeue();

            foreach (var (next, weight) in Graph[node])
            {
                if (edges.ContainsKey(next)) continue;

                edges[next] = edges[node] + 1;
                cost[next] = cost[node] + weight;   // the cost of whatever path BFS took
                queue.Enqueue(next);
            }
        }

        return (edges.GetValueOrDefault(target, -1), cost.GetValueOrDefault(target, -1));
    }

    private static int Dijkstra(int start, int target)
    {
        var best = new Dictionary<int, int> { [start] = 0 };
        var settled = new HashSet<int>();
        var heap = new PriorityQueue<int, int>();
        heap.Enqueue(start, 0);

        while (heap.Count > 0)
        {
            int node = heap.Dequeue();
            if (!settled.Add(node)) continue;

            foreach (var (next, weight) in Graph[node])
            {
                int through = best[node] + weight;

                if (through >= best.GetValueOrDefault(next, int.MaxValue)) continue;

                best[next] = through;
                heap.Enqueue(next, through);
            }
        }

        return best.GetValueOrDefault(target, -1);
    }

    public static void Main()
    {
        var bfs = Bfs(0, 4);

        Console.WriteLine($"BFS to node 4:      {bfs.Edges} edges, total weight {bfs.Cost}");
        Console.WriteLine($"Dijkstra to node 4: total weight {Dijkstra(0, 4)}");

        Console.WriteLine();
        Console.WriteLine("BFS took the two-edge route 0->1->4 costing 20");
        Console.WriteLine("Dijkstra took the three-edge route 0->2->3->4 costing 3");

        Console.WriteLine();
        Console.WriteLine("BFS:      queue, settles by edge count, O(V+E), unweighted only");
        Console.WriteLine("Dijkstra: priority queue, settles by cost, O((V+E) log V), no negatives");
        Console.WriteLine("BFS is Dijkstra with every weight equal to one");
    }
}
```

**Output**

